Here is a complete, robust example of an `onSubmit` function for a React form that sends data to a GraphQL API.

I have designed this to be **production-ready**, handling loading states, error handling, and the specific nuances of GraphQL (variables vs. body).

### The `onSubmit` Function

```javascript
import { useState } from 'react';
import { useMutation } from '@apollo/client';
import { CREATE_USER_MUTATION } from './mutations'; // Import your mutation

export const useUserForm = () => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // 1. Define the mutation hook
  const [createUser, { data, error: mutationError }] = useMutation(CREATE_USER_MUTATION);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      // 2. Gather form data
      const formData = new FormData(e.target);
      const payload = Object.fromEntries(formData.entries());

      // 3. Execute the GraphQL Mutation
      // Note: We pass variables as an object, not the raw body
      const result = await createUser({
        variables: {
          input: payload, // GraphQL expects an 'input' object usually
        },
      });

      // 4. Handle Success
      console.log('Success:', result.data);
      // Reset form or redirect here
    } catch (err) {
      // 5. Handle Errors
      console.error('GraphQL Error:', err);
      setError(err.message || 'An unexpected error occurred');
    } finally {
      setLoading(false);
    }
  };

  return { handleSubmit, loading, error };
};
```

