Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we take the `id` (4 bits) and `size` (3 bits), concatenate them into a 7-bit integer, and write that integer into the `Uint8Array` at the current offset. We then advance the offset by 1 byte (8 bits).
2.  **Unpacking**: We iterate through the `Uint8Array`. For each byte, we extract the lower 4 bits for the `id` and the upper 3 bits for the `size`.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array.
 * 
 * @param {Array} entities - Array of objects with { id: number, size: number }
 * @returns {Uint8Array} - The packed binary data
 */
function packEntities(entities) {
  if (!Array.isArray(entities)) {
    throw new Error("Input must be an array");
  }

  // Calculate total size: 1 byte per entity (4 bits + 3 bits = 7 bits, rounded up to 8 bits)
  const totalSize = entities.length;
  const buffer = new Uint8Array(totalSize);
  let offset = 0;

  for (const entity of entities) {
    // Validate input
    if (typeof entity.id !== 'number' || typeof entity.size !== 'number') {
      throw new Error("Entity must have numeric id and size");
    }

    // Masking to ensure we only use the specified bits
    // id: 4 bits (0-15)
    // size: 3 bits (0-7)
    const packedValue = (entity.id & 0x0F) | ((entity.size & 0x07) << 4);

    buffer[offset] = packedValue;
    offset++;
  }

  return buffer;
}

/**
 * Unpacks a Uint8Array into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed binary data
 * @returns {Array} - Array of objects with { id: number, size: number }
 */
function unpackEntities(buffer) {
  if (!(buffer instanceof Uint8Array)) {
    throw new Error("Input must be a Uint8Array");
  }

  const entities = [];

  for (let i = 0; i < buffer.length; i++) {
    const byte = buffer[i];

    // Extract bits
    // id is in the lower 4 bits
    const id = byte & 0x0F;

    // size is in the upper 3 bits (shifted right by 4)
    const size = (byte >> 4) & 0x07;

    entities.push({ id, size });
  }

  return entities;
}

// --- Example Usage ---

