#### 2. The Backend Code (`server.js`)

This code handles the API endpoint, implements the filtering logic, and handles the "fuzzy" search (finding "Grand" inside "Grand Hotel").

```javascript
require('dotenv').config();
const express = require('express');
const { Pool } = require('pg');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// Database Connection
const pool = new Pool({
  user: 'postgres',
  host: 'localhost',
  database: 'hotel_db',
  password: 'password',
  port: 5432,
});

// 1. Backend Filtering Function
// This function takes a query string and returns matching hotels
const searchHotels = async (query) => {
  if (!query || query.length < 2) return [];

  // We use ILIKE for case-insensitive search and % for wildcards
  // We also limit results to 5 for performance
  const sql = `
    SELECT id, name, city, country, rating 
    FROM hotels 
    WHERE name ILIKE $1 
    OR city ILIKE $1 
    OR country ILIKE $1
    ORDER BY name 
    LIMIT 5
  `;

  const values = [`%${query}%`];

  try {
    const result = await pool.query(sql, values);
    return result.rows;
  } catch (err) {
    console.error('Database Error:', err);
    return [];
  }
};

// 2. API Endpoint
app.get('/api/hotels', async (req, res) => {
  const { q } = req.query; // Get query parameter 'q'

  if (!q) {
    return res.status(400).json({ error: 'Missing query parameter' });
  }

  const hotels = await searchHotels(q);

  // Return JSON response
  res.json({
    query: q,
    results: hotels
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
